    "schemaSnippet": "`SaaSCloudMetrics_2 (record_id BIGINT PRIMARY KEY, region_code VARCHAR(32), cost_usd DECIMAL(10,2), status VARCHAR(20), created_at TIMESTAMP)`",
    "businessObjective": "Group SaaS & Cloud data by region_code, evaluating aggregate functions (COUNT, SUM, AVG, MIN, MAX) and filtering with HAVING.",
    "targetQuery": "SELECT region_code,\n       COUNT(*) AS total_occurrences,\n       ROUND(AVG(cost_usd), 2) AS mean_value\nFROM SaaSCloudMetrics_2\nGROUP BY region_code\nHAVING COUNT(*) >= 25 AND AVG(cost_usd) > 100\nORDER BY total_occurrences DESC;",
    "table": "SaaSCloudMetrics_2"
